/**
 * Complete Multilingual Locales Generator for SamadhanSetu Web Frontend
 * Covers all 14 routes and shared components across all 9 languages.
 */

const fs = require('fs');
const path = require('path');

const LOCALES_DIR = path.join(__dirname, '..', 'src', 'locales');
const LANGS = ['en', 'hi', 'sat', 'nag', 'mun', 'kru', 'kho', 'sad', 'pan'];

const dict = {};
for (const lang of LANGS) {
  dict[lang] = {};
}

function set(ns, key, values) {
  for (const lang of LANGS) {
    if (!dict[lang][ns]) dict[lang][ns] = {};
    if (values[lang] !== undefined) {
      dict[lang][ns][key] = values[lang];
    } else {
      console.warn(`Missing translation for [${lang}]: ${ns}.${key}`);
      dict[lang][ns][key] = values['en'];
    }
  }
}

