for (const lang of LANGS) {
  const filePath = path.join(LOCALES_DIR, `${lang}.json`);
  fs.writeFileSync(filePath, JSON.stringify(dict[lang], null, 2), 'utf-8');
  console.log(`Saved ${lang}.json with ${Object.keys(dict[lang]).length} namespaces.`);
}

